// === Dedup + Relevance Scoring + Sort ===
const items = $input.all();
const seen = new Map();

// High-value keywords for insurance relevance scoring
const highKeywords = ['life insurance', 'annuity', 'retirement', 'pension', 'death benefit', 'whole life', 'term life', 'universal life', 'iul', 'fixed annuity', 'variable annuity'];
const midKeywords = ['insurance', 'coverage', 'premium', 'policy', 'beneficiary', 'underwriting', 'claim', 'financial planning', 'estate', 'wealth', 'tax-deferred'];
const negativeKeywords = ['auto insurance', 'car insurance', 'home insurance', 'property insurance', 'pet insurance', 'travel insurance'];

for (const item of items) {
  const title = (item.json.title || '').trim();
  const titleLower = title.toLowerCase();
  const content = (item.json.content || item.json.contentSnippet || '').toLowerCase();
  const combined = titleLower + ' ' + content;

  // Dedup: normalize title to create a key
  const dedupKey = titleLower.replace(/[^a-z0-9]/g, '').substring(0, 60);
  if (!dedupKey || seen.has(dedupKey)) continue;

  // Relevance scoring
  let score = 0;
  for (const kw of highKeywords) {
    if (combined.includes(kw)) score += 15;
  }
  for (const kw of midKeywords) {
    if (combined.includes(kw)) score += 5;
  }
  for (const kw of negativeKeywords) {
    if (combined.includes(kw)) score -= 20;
  }

  // Skip very low relevance
  if (score < 5) continue;

  item.json._relevanceScore = score;
  item.json._source = 'google_news_rss';
  item.json._fetchDate = new Date().toISOString().split('T')[0];
  seen.set(dedupKey, item);
}

// Sort by score descending
const results = Array.from(seen.values());
results.sort((a, b) => (b.json._relevanceScore || 0) - (a.json._relevanceScore || 0));

// Return top results (will be limited by next node)
return results;

// === Parse AI Output & Build Final Record ===
const items = $input.all();
const results = [];

for (const item of items) {
  const raw = item.json;
  let aiOutput;

  try {
    // Try to parse the AI response as JSON
    let responseText = raw.text || raw.message?.content || raw.choices?.[0]?.message?.content || '';
    // Remove markdown code block markers if present
    responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    aiOutput = JSON.parse(responseText);
  } catch (e) {
    // If parsing fails, create a fallback
    aiOutput = {
      zh_title: '(AI解析失败) ' + (raw.title || '未知标题'),
      zh_summary: '内容解析失败，请人工审核',
      zh_content_html: '<p>AI 内容生成失败，原始链接：' + (raw.link || '') + '</p>',
      category: 'industry_news',
      image_prompt: 'professional insurance office with warm lighting, modern design',
      tags: ['待审核']
    };
  }

  // Build image URL via Pollinations AI
  const imageUrl = 'https://image.pollinations.ai/prompt/' + encodeURIComponent(aiOutput.image_prompt || 'professional insurance concept');

  // Get original item data from the previous RSS nodes
  const originalTitle = raw.title || '';
  const originalLink = raw.link || '';
  const originalPubDate = raw.pubDate || '';
  const fetchDate = raw._fetchDate || new Date().toISOString().split('T')[0];

  results.push({
    json: {
      zh_title: aiOutput.chinese_title || aiOutput.zh_title,
      zh_summary: aiOutput.chinese_summary || aiOutput.zh_summary,
      zh_content_html: aiOutput.chinese_content_html || aiOutput.zh_content_html,
      category: aiOutput.category,
      tags: (aiOutput.tags || []).join(', '),
      image_prompt: aiOutput.image_prompt,
      image_url: imageUrl,
      original_title: originalTitle,
      original_link: originalLink,
      original_pub_date: originalPubDate,
      fetch_date: fetchDate,
      publish_date: new Date().toISOString(),
      status: 'pending_review',
      content_type: 'newsletter',
      relevance_score: raw._relevanceScore || 0
    }
  });
}

return results;
